BEGIN;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='concept_id_kind_unique' AND conrelid='canonical_concepts'::regclass) THEN ALTER TABLE canonical_concepts ADD CONSTRAINT concept_id_kind_unique UNIQUE(id,kind); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='identifier_entity_matches_concept' AND conrelid='concept_identifiers'::regclass) THEN ALTER TABLE concept_identifiers ADD CONSTRAINT identifier_entity_matches_concept FOREIGN KEY(concept_id,entity_kind) REFERENCES canonical_concepts(id,kind); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='identifier_scheme_has_entity_kind' AND conrelid='concept_identifiers'::regclass) THEN ALTER TABLE concept_identifiers ADD CONSTRAINT identifier_scheme_has_entity_kind CHECK((scheme NOT IN ('PubChemCID','InChIKey') OR entity_kind='chemical_compound') AND (scheme NOT IN ('RxCUI') OR entity_kind IN ('ingredient','precise_ingredient','clinical_drug')) AND (scheme NOT IN ('SPL_SET_ID','NDC') OR entity_kind='product') AND (scheme NOT IN ('DOI','PMID','PMCID','NCT') OR entity_kind='research')); END IF; END $$;
CREATE OR REPLACE VIEW public_medical_sources AS SELECT s.id,s.source_title,s.source_url,s.publisher,s.license,s.attribution,p.registry,p.usage_mode,p.offline_metadata_allowed,p.terms_checked_at,coalesce(c.health_status,'unknown') AS health_status,c.last_success_at,c.last_error_at,c.error_code,p.enabled FROM sources s JOIN source_policies p ON p.source_id=s.id LEFT JOIN source_connector_status c ON c.source_id=s.id;
CREATE OR REPLACE FUNCTION flag_source_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.payload_hash<>NEW.payload_hash THEN INSERT INTO content_change_events(source_id,source_native_id,previous_hash,new_hash,kind) VALUES(NEW.source_id,NEW.source_native_id,OLD.payload_hash,NEW.payload_hash,'source_changed_requires_review'); UPDATE knowledge_facts SET stale_state=true WHERE source_id=NEW.source_id AND source_native_id=NEW.source_native_id AND payload_hash<>NEW.payload_hash; UPDATE canonical_concepts SET stale=true WHERE id IN(OLD.canonical_id,NEW.canonical_id); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION flag_retracted_reference() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.retraction_state IN ('retracted','corrected') AND NEW.retraction_state IS DISTINCT FROM OLD.retraction_state THEN UPDATE canonical_concepts SET stale=true WHERE id IN (SELECT concept_id FROM citation_links WHERE reference_id=NEW.concept_id); UPDATE content_items SET source_stale=true,status=CASE WHEN clinical THEN 'needs_review' ELSE status END,review_status=CASE WHEN clinical THEN 'needs_review' ELSE review_status END WHERE canonical_id IN (SELECT content_id FROM citation_links WHERE reference_id=NEW.concept_id); INSERT INTO content_change_events(source_id,source_native_id,new_hash,kind) SELECT r.source_id,r.source_native_id,r.payload_hash,NEW.retraction_state FROM source_records r WHERE r.canonical_id=NEW.concept_id ORDER BY r.fetched_at DESC LIMIT 1; END IF; RETURN NEW; END $$;
INSERT INTO schema_migrations(version) VALUES(5) ON CONFLICT DO NOTHING;
COMMIT;
